BEGIN;

CREATE TABLE public."all_sale" (
  "id_sale" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "sale_date" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "store_count" INTEGER NOT NULL,
  "sum_amount" BIGINT DEFAULT 0 NOT NULL,
  "store_type" VARCHAR(20) NOT NULL,
  "man10" BIGINT DEFAULT 0 NOT NULL,
  "man20" BIGINT DEFAULT 0 NOT NULL,
  "man30" BIGINT DEFAULT 0 NOT NULL,
  "man40" BIGINT DEFAULT 0 NOT NULL,
  "man50" BIGINT DEFAULT 0 NOT NULL,
  "man60" BIGINT DEFAULT 0 NOT NULL,
  "woman10" BIGINT DEFAULT 0 NOT NULL,
  "woman20" BIGINT DEFAULT 0 NOT NULL,
  "woman30" BIGINT DEFAULT 0 NOT NULL,
  "woman40" BIGINT DEFAULT 0 NOT NULL,
  "woman50" BIGINT DEFAULT 0 NOT NULL,
  "woman60" BIGINT DEFAULT 0 NOT NULL,
  "day" VARCHAR(5) DEFAULT '' NOT NULL,
  "kind_day" VARCHAR(20),
  "1+1_event_count" INTEGER,
  "2+1_event_count" INTEGER,
  "event_img" INTEGER,
  "sum_amount_growth" DOUBLE PRECISION,
  "avg_sum_amount_growth" DOUBLE PRECISION,
  "growth_deviation" DOUBLE PRECISION,
  PRIMARY KEY ("id_sale")
);

CREATE TABLE public."event_img" (
  "img_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "img_url" TEXT,
  "start_date" TIMESTAMP WITHOUT TIME ZONE,
  "end_date" TIMESTAMP WITHOUT TIME ZONE,
  "event_title" VARCHAR(50) NOT NULL,
  "store_type" VARCHAR(20) NOT NULL,
  "idx" INTEGER,
  PRIMARY KEY ("img_id")
);

CREATE TABLE public."event_plus" (
  "plus_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "store_type" VARCHAR(20) NOT NULL,
  "update_date" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "plus_price" INTEGER NOT NULL,
  "plus_event_price" INTEGER NOT NULL,
  "plus_type" VARCHAR(10) NOT NULL,
  "plus_title" VARCHAR(50) NOT NULL,
  PRIMARY KEY ("plus_id")
);

CREATE TABLE public."hospital_sale" (
  "id_sale" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "store_type" VARCHAR(20),
  "sale" INTEGER,
  "store_count" INTEGER,
  "sale_date" TIMESTAMP WITHOUT TIME ZONE,
  PRIMARY KEY ("id_sale")
);

CREATE TABLE public."naver_search_trend" (
