  "news_agency" VARCHAR(20),
  "store_type" VARCHAR(5),
  "news_start" INTEGER DEFAULT 0,
  PRIMARY KEY ("news_id")
);

CREATE TABLE public."people" (
  "code" BIGINT,
  "region" VARCHAR(50),
  "people" INTEGER,
  "man" INTEGER,
  "woman" INTEGER,
  "gs25" DOUBLE PRECISION,
  "cu" DOUBLE PRECISION,
  "seven" DOUBLE PRECISION,
  "gc_type" VARCHAR(50),
  "cleanaddr" VARCHAR(50),
  "x" DOUBLE PRECISION,
