  "store_type" VARCHAR(20),
  PRIMARY KEY ("video_id")
);

CREATE INDEX "all_sale_date_store_idx" ON public."all_sale" ("sale_date", lower(store_type));
CREATE INDEX "news_search_date_store_idx" ON public."news_search" ("news_date", lower(store_type));
CREATE INDEX "ytb_video_date_store_idx" ON public."ytb_video" ("published_at", lower(store_type));

COMMIT;
